// Claude's review tests for A3 (the Test bar). agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, newProject, type Mock } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

function mock(id: string, urlPattern: string, extra: Partial<Mock> = {}): Mock {
  return {
    id,
    name: id,
    enabled: true,
    method: 'ANY',
    urlPattern,
    response: { status: 200, headers: { 'content-type': 'application/json' }, body: '{"from":"fixed"}', bodyEncoding: 'text', delayMs: 0 },
    source: 'manual',
    createdAt: 0,
    ...extra,
  };
}

async function openPanel(): Promise<{ page: Page; panel: Page }> {
  const project = newProject('p1', fixture.origin);
  project.scenarios[0]!.mocks.push(
    mock('Doc one', '/doc/1', { response: { status: 404, headers: { 'x-a': '1' }, body: 'gone', bodyEncoding: 'text', delayMs: 0 } }),
    mock('Doc by id', '/doc/:id', { reply: 'code', code: 'res.status = 202; return { id: params.id, q: query.q, b: body && body.n };' }),
    mock('Broken', '/broken', { reply: 'code', code: "throw new Error('nope')" }),
    mock('Picture', '/pic', { response: { status: 200, headers: { 'content-type': 'image/png' }, body: 'AAEC', bodyEncoding: 'base64', delayMs: 0 } }),
  );
  project.scenarios.push({ id: 's2', name: 'Errors', mocks: [mock('Doc err', '/doc/:id', { response: { status: 503, headers: {}, body: 'down', bodyEncoding: 'text', delayMs: 0 } })] });
  await session.setState({ ...emptyState(), projects: [project], enabledOrigins: [fixture.origin] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  await panel.getByTestId('tab-mocks').click();
  await expect(panel.getByTestId('test-bar')).toBeVisible();
  return { page, panel };
}

async function runTest(panel: Page, url: string, method = 'GET', body?: string) {
  await panel.getByTestId('test-method').selectOption(method);
  await panel.getByTestId('test-url').fill(url);
  if (body !== undefined) await panel.getByTestId('test-body').fill(body);
  await panel.getByTestId('test-run').click();
}

test('a fixed mock: shows the match, status, headers and body', async () => {
  const { page, panel } = await openPanel();
  try {
    await runTest(panel, '/doc/1');
    await expect(panel.getByTestId('test-match')).toContainText('Doc one');
    await expect(panel.getByTestId('test-scenario')).toHaveText('Default');
    await expect(panel.getByTestId('test-status')).toHaveText('404 Not Found');
    await expect(panel.getByTestId('test-headers')).toContainText('x-a: 1');
    await expect(panel.getByTestId('test-body-out')).toHaveText('gone');
    await expect(panel.getByTestId('test-nomatch')).toHaveCount(0);
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a code mock runs for real with params, query and body', async () => {
  const { page, panel } = await openPanel();
  try {
    await runTest(panel, '/doc/7?q=x', 'POST', '{"n":3}');
    await expect(panel.getByTestId('test-match')).toContainText('Doc by id');
    await expect(panel.getByTestId('test-status')).toHaveText('202 Accepted');
    await expect(panel.getByTestId('test-body-out')).toHaveText('{"id":"7","q":"x","b":3}');
    await expect(panel.getByTestId('test-headers')).toContainText('content-type: application/json');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a failing code mock shows its error and the 500 reply', async () => {
  const { page, panel } = await openPanel();
  try {
    await runTest(panel, '/broken');
    await expect(panel.getByTestId('test-error')).toHaveText('Code failed: nope');
    await expect(panel.getByTestId('test-status')).toHaveText('500 Internal Server Error');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('no match says the real server answers; a bad URL says so', async () => {
  const { page, panel } = await openPanel();
  try {
    await runTest(panel, '/nothing/here');
    await expect(panel.getByTestId('test-nomatch')).toHaveText('No mock — the real server answers');
    await expect(panel.getByTestId('test-match')).toHaveCount(0);
    await runTest(panel, 'http://');
    await expect(panel.getByTestId('test-url-error')).toHaveText('Not a valid URL');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a binary body shows its size and type, not raw base64', async () => {
  const { page, panel } = await openPanel();
  try {
    await runTest(panel, '/pic');
    await expect(panel.getByTestId('test-body-out')).toHaveText('3 bytes, image/png');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the active scenario wins, and clicking the match opens that mock', async () => {
  const { page, panel } = await openPanel();
  try {
    await panel.getByTestId('scenario-chip').filter({ hasText: 'Errors' }).click();
    await runTest(panel, '/doc/5');
    await expect(panel.getByTestId('test-match')).toContainText('Doc err');
    await expect(panel.getByTestId('test-scenario')).toHaveText('Errors');
    await expect(panel.getByTestId('test-status')).toHaveText('503 Service Unavailable');

    // Select Default in the left list first, so opening must move it to Errors.
    await panel.locator('.scenario-group-header', { hasText: 'Default' }).click();
    await expect(panel.locator('.scenario-group.selected')).toContainText('Default');
    await panel.getByTestId('test-open').click();
    await expect(panel.getByTestId('field-name')).toHaveValue('Doc err');
    // The left list also moves to that scenario, with the mock's row selected.
    await expect(panel.locator('.scenario-group.selected')).toContainText('Errors');
    await expect(panel.locator('.scenario-group.selected [data-testid="mock-row"].selected')).toContainText('Doc err');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('Enter in the URL box runs the test; the body box shows only for methods with a body', async () => {
  const { page, panel } = await openPanel();
  try {
    await panel.getByTestId('test-method').selectOption('GET');
    await expect(panel.getByTestId('test-body')).toHaveCount(0);
    await panel.getByTestId('test-method').selectOption('PUT');
    await expect(panel.getByTestId('test-body')).toBeVisible();
    await panel.getByTestId('test-method').selectOption('GET');
    await panel.getByTestId('test-url').fill('/doc/1');
    await panel.getByTestId('test-url').press('Enter');
    await expect(panel.getByTestId('test-status')).toHaveText('404 Not Found');
  } finally {
    await panel.close();
    await page.close();
  }
});
